c=cell
def H(s,ur,en,ps): add(s,f'h{len(s["paras"])+1}',en,ur,ps,kind='heading')
def P(s,ur,en,ps,**m): add(s,f'p{len(s["paras"])+1}',en,ur,ps,**m)
def A(s,ar,ur,en,ps):
    add(s,f'a{len(s["paras"])+1}',ar+'\n'+en,ar+'\n'+ur,ar+'\n'+ps,kind='quran')
def I(s,items,g):
    for ur,en,ps in items: add(s,f'i{len(s["paras"])+1}',en,ur,ps,listGroup=g)
def Q(s,ur,en,ps,u='l01',**k): add(s,f'q{len(s["paras"])+1}',en,ur,ps,role='question',exerciseId=f'mq11-{u}-q',tab='exercise',**k)
def O(s,ur,en,ps,u='l01'): add(s,f'o{len(s["paras"])+1}',en,ur,ps,role='option',exerciseId=f'mq11-{u}-q',tab='exercise')
def MC(s,q,vals):
    Q(s,*q)
    for a,e,v in zip(['الف','ب','ج','د'],['a','b','c','d'],vals):
        O(s,f'{a}) {v[0]}',f'({e}) {v[1]}',f'{a}) {v[2]}')
